<?php
declare(strict_types=1);
namespace App\Application\QuestionBank\Service;
use App\Application\Assistant\Port\AssistantProviderInterface;use App\Application\Catalog\Port\PdfTextExtractorInterface;use App\Application\QuestionBank\DTO\Response\QuestionPdfAssistanceResponseDto;use App\Domain\Assistant\ValueObject\SyllabusEvidence;use App\Domain\QuestionBank\Repository\QuestionPdfEvidenceSourceRepositoryInterface;
final class AskQuestionWithPdfEvidenceService { public function __construct(private readonly QuestionPdfEvidenceSourceRepositoryInterface $sources,private readonly PdfTextExtractorInterface $pdf,private readonly AssistantProviderInterface $assistant){} public function ask(string $questionId,string $doubt):QuestionPdfAssistanceResponseDto {if(mb_strlen(trim($doubt))<3)throw new \InvalidArgumentException('Descreva sua dúvida.');$source=$this->sources->findPublishedSource($questionId);if($source===null)throw new \DomainException('Esta questão não possui PDF de origem disponível.');$all=$this->pdf->extractPages($source->documentPath);$evidence=[];foreach($source->pages as $page)if(isset($all[$page-1]))$evidence[]=new SyllabusEvidence($page,mb_substr($all[$page-1],0,14000));if($evidence===[])throw new \DomainException('As páginas de origem não puderam ser recuperadas.');$prompt='Responda à dúvida do aluno somente com base nas páginas do PDF de origem fornecidas. Não invente informações, não revele gabarito se isso não estiver explicitamente solicitado e indique limites da evidência. Questão: '.mb_substr($source->statement,0,4000).' Dúvida: '.trim($doubt);$answer=$this->assistant->answer($prompt,$evidence);return new QuestionPdfAssistanceResponseDto($answer->content,$answer->provider,$answer->model,array_map(static fn(SyllabusEvidence $item):int=>$item->pageNumber,$answer->evidence));} }
